const visibleRows = dataRows.slice(0, maxDisplay);
const truncated = dataRows.length > maxDisplay;

let out = '<div class="ai-table-container">';

if (enableTableDownload && dataRows.length > 0) {
  const tableJson = JSON.stringify({ headers: headers, rows: dataRows })
    .replace(/&/g, '&amp;').replace(/"/g, '&quot;');
  const dlSvg = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>';

  // Detect sensor tables by header — render <a> links pointing directly
  // to /api/sensors/export (same pattern as track downloads).
  // For all other tables keep blob-based <button> downloads.
  const isSensorTable = headers.some(h => /device.?id/i.test(h.trim()));
  const date = new Date().toISOString().slice(0, 10);

  out += '<div class="table-download-bar" data-table="' + tableJson + '">';
  if (isSensorTable) {
    // <a> tags → server handles format + filename (no JS state needed).
    // Default to world-bounds; export chunk will refine href if needed.
    out += '<a class="table-download-btn" data-fmt="csv" href="/api/sensors/export?format=csv" download="safecast_sensors_' + date + '.csv" title="Download as CSV">' + dlSvg + ' CSV</a>';
    out += '<a class="table-download-btn excel" data-fmt="excel" href="/api/sensors/export?format=xlsx" download="safecast_sensors_' + date + '.xls" title="Download as Excel">' + dlSvg + ' Excel</a>';
    out += '<a class="table-download-btn json" data-fmt="json" href="/api/sensors/export?format=json" download="safecast_sensors_' + date + '.json" title="Download as JSON">' + dlSvg + ' JSON</a>';
    out += '<span class="table-rows-info">showing ' + Math.min(maxDisplay, dataRows.length) + ' of … rows — download for all</span>';
  } else {
    out += '<button class="table-download-btn" data-fmt="csv" title="Download as CSV">' + dlSvg + ' CSV</button>';
    out += '<button class="table-download-btn excel" data-fmt="excel" title="Download as Excel">' + dlSvg + ' Excel</button>';
    out += '<button class="table-download-btn json" data-fmt="json" title="Download as JSON">' + dlSvg + ' JSON</button>';
    if (dataRows.length > maxDisplay) {
      out += '<span class="table-rows-info">showing ' + maxDisplay + ' of ' + dataRows.length + ' rows — download for all</span>';
    } else {
      out += '<span class="table-rows-info">' + dataRows.length + ' rows</span>';
    }
  }
  out += '</div>';
}

out += '<table class="ai-table">';

// Header row
out += '<tr>';
headers.forEach(col => { out += `<th>${col}</th>`; });
out += '</tr>';

// Data rows — only show up to maxDisplay
visibleRows.forEach(cols => {
  out += '<tr>';
  cols.forEach(col => { out += `<td>${col}</td>`; });
  out += '</tr>';
});

