file.content:
const lines = buffer.split('\n');
buffer = lines.pop();

for (const line of lines) {
  if (!line.trim()) continue;
  try {
    const ev = JSON.parse(line);
    if (ev.type === 'text') {
      if (botBubble.classList.contains('ai-thinking')) {
        botBubble.classList.remove('ai-thinking');
        accumulated = '';
      }
      accumulated += ev.text;
      botBubble.innerHTML = markdownToHTML(accumulated);
      messagesEl.scrollTop = messagesEl.scrollHeight;
    } else if (ev.type === 'action' || ev.action) {
      executeMapAction(ev);
    } else if (ev.type === 'export') {
      // Save for after finish() re-renders innerHTML with enableTableDownload=true
      console.log('[export chunk]', ev);
      pendingExportChunk = ev;
    } else if (ev.type === 'done') {
      if (ev.chat_id) { chatID = ev.chat_id; isCached = !!ev.cached; }
      finish(true);
    } else if (ev.type === 'error') {
      botBubble.textContent = translate('ai_error') + ev.error;
      botBubble.classList.remove('ai-thinking');
      finish(false);
    }
  } catch (e) { }

