function finish(success) {
  if (finished) return;
  finished = true;
  botBubble.classList.remove('ai-thinking');
  // Re-render with download buttons now that the full response is in
  if (success && accumulated) {
    botBubble.innerHTML = markdownToHTML(accumulated, true);
    // Refine sensor <a> download links with the specific export URL
    // (bounds the AI actually used). Falls back to world-bounds default
    // already set in the href. Also updates the row count label.
    if (pendingExportChunk) {
      const date = new Date().toISOString().slice(0, 10);
      botBubble.querySelectorAll('a.table-download-btn[data-fmt]').forEach(function(a) {
        const fmt = a.dataset.fmt || 'csv';
        const serverFmt = fmt === 'excel' ? 'xlsx' : fmt;
        const ext = fmt === 'excel' ? 'xls' : fmt;
        const base = pendingExportChunk.export_url || '/api/sensors/export';
        a.href = base + '&format=' + serverFmt;
        a.download = 'safecast_sensors_' + date + '.' + ext;
      });
      const total = pendingExportChunk.export_total;
      if (total) {
        const info = botBubble.querySelector('.table-rows-info');
        if (info) {
          info.textContent = total > 10
            ? 'showing 10 of ' + total + ' rows — download for all'
            : total + ' rows';
        }
      }
      pendingExportChunk = null;
    }
  }
  busy = false;
  sendBtn.disabled = false;
  msgInput.focus();
  if (success && accumulated) {
    chatHistory.push(
      { role: 'user', content: text },
      { role: 'assistant', content: accumulated }
    );
    if (chatHistory.length > 10) {
      chatHistory = chatHistory.slice(-10);
    }
    if (chatID) {
      const wrapper = botBubble.parentElement;
      addFeedbackRow(wrapper, chatID, isCached);
    }
  }
}

