// @Router      /api/admin/mcp/delete [delete]
// @Router      /api/admin/mcp/delete [post]
func adminMCPDeleteHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodDelete && r.Method != http.MethodPost {
