		"thumbs_up", "thumbs_down",
	},
	"mcp_query_log": {
		"tool_name", "created_at", "duration_ms", "result_count",
		"client_info", "params",
	},
	"mcp_ai_query_log": {
		"user_id", "user_email", "session_id", "timestamp",
		"tool_name", "generated_query", "duration_ms",
		"commit_hash", "error",
	},
