function markdownToHTML(text, enableTableDownload) {
  if (!text) return '';

  // Extract sensor export marker BEFORE HTML escaping so the URL is intact.
  // The AI emits: ⬇ export:/api/sensors/export?... total:N
  let exportUrl = null;
  let exportTotal = null;
  text = text.replace(/^⬇ export:(\S+)\s+total:(\d+)\s*$/m, function(_, url, total) {
    exportUrl = url;
    exportTotal = parseInt(total, 10);
    return ''; // remove this line from displayed text
  });

  let html = text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/### (.+)/g, '<h3 style="margin: 20px 0 10px 0; font-size: 16px; font-weight: 700;">$1</h3>')
    .replace(/## (.+)/g, '<h2 style="margin: 24px 0 12px 0; font-size: 18px; font-weight: 700;">$1</h2>')
    .replace(/# (.+)/g, '<h1 style="margin: 28px 0 14px 0; font-size: 20px; font-weight: 700;">$1</h1>')
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/\*(.+?)\*/g, '<em>$1</em>')
    .replace(/`([^`]+)`/g, '<code style="background: var(--control-bg); padding: 2px 5px; border-radius: 4px; font-size: 0.9em;">$1</code>')
    .replace(/\[(.+?)\]\((.+?)\)/g, '<a href="$2" target="_blank">$1</a>');

  // Markdown Table parser — line-by-line to avoid regex stack overflow on large tables.
  // Finds consecutive lines starting with | and renders them as HTML tables.
  // Handles incomplete/truncated tables (e.g. cut off mid-row by token limit).
  const lines = html.split('\n');
  const tableBlocks = []; // [{start, end}] indices into lines[]
  let tStart = -1;
  for (let i = 0; i <= lines.length; i++) {
    const isTableLine = i < lines.length && lines[i].trimStart().startsWith('|');
    if (isTableLine && tStart === -1) { tStart = i; }
    else if (!isTableLine && tStart !== -1) {
      if (i - tStart >= 2) tableBlocks.push({start: tStart, end: i});
      tStart = -1;
    }
  }
  // Process blocks in reverse so indices stay valid as we splice
  for (let b = tableBlocks.length - 1; b >= 0; b--) {
    const {start, end} = tableBlocks[b];
    const tableLines = lines.slice(start, end);
    const rendered = (function(tableLines) {
    let rows = tableLines.map(r => r.trim()).filter(r => r.length > 0);
    if (rows.length < 2) return rows.join('\n');

    let bodyRows = [];

    rows.forEach((row) => {
      if (row.match(/^\|?[\s|:-]+\|?$/)) return; // separator row

      let cols = row.split('|');
      // Remove leading/trailing empty cells if pipes were used as borders
      if (row.startsWith('|')) cols.shift();
      if (row.endsWith('|')) cols.pop();
      bodyRows.push(cols.map(c => c.trim()));
    });

    const headers = bodyRows[0] || [];
    const dataRows = bodyRows.slice(1);
    const maxDisplay = 10;
    const visibleRows = dataRows.slice(0, maxDisplay);
    const truncated = dataRows.length > maxDisplay;
    const isSensorTable = headers.some(h => /device.?id/i.test(h.trim()));

    let out = '<div class="ai-table-container">';

    if (enableTableDownload && dataRows.length > 0) {
      const tableJson = JSON.stringify({ headers: headers, rows: dataRows })
        .replace(/&/g, '&amp;').replace(/"/g, '&quot;');
      const dlSvg = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="7 10 12 15 17 10"/><line x1="12" y1="15" x2="12" y2="3"/></svg>';

      // Detect sensor tables by header — render <a> links pointing directly
      // to /api/sensors/export (same pattern as track downloads).
      // For all other tables keep blob-based <button> downloads.
      const date = new Date().toISOString().slice(0, 10);

      out += '<div class="table-download-bar" data-table="' + tableJson + '">';
      if (isSensorTable) {
        // <a> tags → server handles format + filename (no JS state needed).
        // Default to world-bounds; export chunk will refine href if needed.
        out += '<a class="table-download-btn" data-fmt="csv" href="/api/sensors/export?format=csv" download="safecast_sensors_' + date + '.csv" title="Download as CSV">' + dlSvg + ' CSV</a>';
        out += '<a class="table-download-btn excel" data-fmt="excel" href="/api/sensors/export?format=xlsx" download="safecast_sensors_' + date + '.xls" title="Download as Excel">' + dlSvg + ' Excel</a>';
        out += '<a class="table-download-btn json" data-fmt="json" href="/api/sensors/export?format=json" download="safecast_sensors_' + date + '.json" title="Download as JSON">' + dlSvg + ' JSON</a>';
        out += '<span class="table-rows-info">showing ' + Math.min(maxDisplay, dataRows.length) + ' of … rows — download for all</span>';
      } else {
        out += '<button class="table-download-btn" data-fmt="csv" title="Download as CSV">' + dlSvg + ' CSV</button>';
        out += '<button class="table-download-btn excel" data-fmt="excel" title="Download as Excel">' + dlSvg + ' Excel</button>';
        out += '<button class="table-download-btn json" data-fmt="json" title="Download as JSON">' + dlSvg + ' JSON</button>';
        if (dataRows.length > maxDisplay) {
          out += '<span class="table-rows-info">showing ' + maxDisplay + ' of ' + dataRows.length + ' rows — download for all</span>';
        } else {
          out += '<span class="table-rows-info">' + dataRows.length + ' rows</span>';
        }
      }
      out += '</div>';
    }

    out += '<table class="ai-table">';

    // Header row
    out += '<tr>';
    headers.forEach(col => { out += `<th>${col}</th>`; });
    out += '</tr>';

    // Data rows — only show up to maxDisplay
    visibleRows.forEach(cols => {
      out += '<tr>';
      cols.forEach(col => { out += `<td>${col}</td>`; });
      out += '</tr>';
    });

    if (truncated && !isSensorTable) {
      out += `<tr><td colspan="${headers.length}" style="text-align:center;opacity:0.5;font-style:italic;padding:8px;">… ${dataRows.length - maxDisplay} more rows — download to see all</td></tr>`;
    }

    out += '</table></div>';
    return out;
    })(tableLines);
    lines.splice(start, end - start, rendered);
  }
  html = lines.join('\n');

  // Handle line breaks ONLY if they are not inside a table-container
  let parts = html.split(/(<div class="ai-table-container">[\s\S]*?<\/div>)/g);
  html = parts.map(part => {
    if (part.startsWith('<div class="ai-table-container">')) return part;
    return part.replace(/\n\n/g, '<br><br>').replace(/\n/g, '<br>');
  }).join('');

